import sys
sys.path.insert(0, 'work/repo')
from boltons.cacheutils import LRI, LRU

results = []
def check(name, fn):
    try:
        r = fn()
        results.append((name, 'OK', repr(r)))
    except Exception as e:
        results.append((name, 'FAIL', '%s: %s' % (type(e).__name__, e)))

def repro_paths():
    c = LRU()
    c['color'] = 'red'
    c['color'] = 'blue'
    return {
        'c[key]': c['color'],
        'get': c.get('color'),
        'dict()': dict(c),
        'values': list(c.values()),
        'items': list(c.items()),
        'iter': list(c),
        'repr_has_red': 'red' in repr(c),
        'copy_dict': dict(c.copy()),
        'len': len(c),
        'eq_new': c == {'color': 'blue'},
        'eq_old': c == {'color': 'red'},
        'ne_old': c != {'color': 'red'},
        'setdefault': c.setdefault('color', 'green'),
    }
check('all read paths after overwrite', repro_paths)

def pop_after_overwrite():
    c = LRU(); c['k']='v1'; c['k']='v2'
    return c.pop('k'), dict(c)
check('pop after overwrite', pop_after_overwrite)

def popitem_after_overwrite():
    c = LRU(); c['k']='v1'; c['k']='v2'
    return c.popitem(), dict(c)
check('popitem after overwrite', popitem_after_overwrite)

def lru_overwrite_recency():
    c = LRU(max_size=2)
    c['a'] = 1; c['b'] = 2
    c['a'] = 'A'
    c['c'] = 3
    assert 'b' not in c and 'a' in c and 'c' in c, dict(c)
    return dict(c), c._get_flattened_ll()
check('LRU: overwrite protects key from eviction', lru_overwrite_recency)

def lru_overwrite_old_still_evicted():
    c = LRU(max_size=2)
    c['a'] = 1; c['b'] = 2
    c['b'] = 'B'
    c['c'] = 3
    assert 'a' not in c and 'b' in c and 'c' in c, dict(c)
    return dict(c)
check('LRU: evict the non-overwritten key', lru_overwrite_old_still_evicted)

def lru_maxsize1_overwrite():
    c = LRU(max_size=1)
    c['a'] = 1
    c['a'] = 2
    assert len(c) == 1 and c['a'] == 2, dict(c)
    c['b'] = 3
    assert dict(c) == {'b': 3}, dict(c)
    return dict(c)
check('LRU max_size=1 overwrite then evict', lru_maxsize1_overwrite)

def lri_overwrite_recency():
    c = LRI(max_size=2)
    c['a']=1; c['b']=2
    c['a']='A'
    c['c']=3
    assert 'b' not in c and 'a' in c and 'c' in c, dict(c)
    return dict(c)
check('LRI: reinsert existing key changes eviction', lri_overwrite_recency)

def stats():
    c = LRU()
    c['color']='red'; c['color']='blue'
    _ = c['color']; c.get('color'); c.get('nope', 0)
    _ = c == {'color':'blue'}
    return (c.hit_count, c.miss_count, c.soft_miss_count)
check('stats after overwrite/eq (expect 1,1,1)', stats)

def doctest_counts():
    cap_cache = LRI(max_size=2)
    cap_cache['a'], cap_cache['b'] = 'A', 'B'
    dict(cap_cache)
    [cap_cache['b'] for i in range(3)][0]
    cap_cache['c'] = 'C'
    cap_cache.get('a')
    return (cap_cache.hit_count, cap_cache.miss_count, cap_cache.soft_miss_count)
check('LRI doctest counts (3,1,1)', doctest_counts)

def doctest_counts_lru():
    cap_cache = LRU(max_size=2)
    cap_cache['a'], cap_cache['b'] = 'A', 'B'
    dict(cap_cache)
    [cap_cache['b'] for i in range(3)][0]
    cap_cache['c'] = 'C'
    cap_cache.get('a')
    return (cap_cache.hit_count, cap_cache.miss_count, cap_cache.soft_miss_count)
check('LRU doctest counts (3,1,1)', doctest_counts_lru)

def eq_matrix():
    out = {}
    c = LRU(); c['color']='red'; c['color']='blue'
    for name, expr in [
        ('LRU()=={}', lambda: LRU() == {}),
        ('LRU()==LRU()', lambda: LRU() == LRU()),
        ('LRI()==LRU()', lambda: LRI() == LRU()),
        ('eq dict same', lambda: c == {'color':'blue'}),
        ('eq dict diff', lambda: c == {'color':'red'}),
        ('ne dict diff', lambda: c != {'color':'red'}),
        ('dict==cache', lambda: {'color':'blue'} == c),
        ('eq LRI same', lambda: LRI(max_size=9, values={'color':'blue'}) == c),
        ('eq LRI diff-content', lambda: LRI(max_size=9, values={'color':'red'}) == c),
        ('eq LRI diff-len', lambda: LRI(values={'a':1}) == c),
        ('eq cache to itself', lambda: c == c),
        ('eq list', lambda: c == ['color']),
        ('eq int', lambda: c == 5),
        ('eq None', lambda: c == None),
        ('ne None', lambda: c != None),
        ('both sides', lambda: (c == {'color':'blue'}, {'color':'blue'} == c)),
    ]:
        try:
            out[name] = repr(expr())
        except Exception as e:
            out[name] = 'EXC %s: %s' % (type(e).__name__, e)
    return out
check('equality matrix', eq_matrix)

def copy_freshness():
    c = LRU(); c['k']='v1'; c['k']='v2'
    cp = c.copy()
    d = LRU(); d.update(c)
    return dict(cp), dict(d), list(cp.values())
check('copy/update carry new value', copy_freshness)

def sync_stress():
    import random
    random.seed(0)
    for cls in (LRI, LRU):
        c = cls(max_size=5)
        for i in range(500):
            k = random.randrange(8)
            op = random.random()
            if op < 0.6: c[k] = i
            elif op < 0.75:
                try: c.pop(k)
                except KeyError: pass
            elif op < 0.85:
                try: del c[k]
                except KeyError: pass
            elif op < 0.9: c.get(k)
            else:
                try: c.popitem()
                except KeyError: pass
            ll_keys = set(x for x, v in c._get_flattened_ll() if str(x) != '_MISSING')
            dict_keys = set(dict(c))
            if ll_keys != dict_keys:
                return 'DESYNC at %s iter %d: ll=%s dict=%s' % (cls.__name__, i, sorted(map(str,ll_keys)), sorted(map(str,dict_keys)))
            if len(c) > 5:
                return 'OVERFLOW %s: %d' % (cls.__name__, len(c))
            for key in dict_keys:
                if c[key] != dict(c)[key]:
                    return 'STALE %s: key %r link=%r dict=%r' % (cls.__name__, key, c[key], dict(c)[key])
    return 'in sync'
check('stress ll/dict sync', sync_stress)

for name, status, detail in results:
    print('%-4s %-45s %s' % (status, name, detail))
EOF
