from boltons.iterutils import backoff, backoff_iter

def call(fn, *a, **k):
    try:
        return ('ok', fn(*a, **k))
    except Exception as e:
        return ('err', type(e).__name__, str(e))

# Grid: factor=1.0, count=None. Oracle: can the loop sequence reach stop?
def reachable(start, stop):
    # replicate loop dynamics for factor=1.0
    cur, n = float(start), 0
    seen = []
    while n < 10:
        seen.append(cur)
        if cur == stop:
            return n + 1  # count that reaches stop
        n += 1
        if cur == 0: cur = 1
        elif cur < stop: cur *= 1.0
        if cur > stop: cur = stop
        if seen.count(cur) > 2 and cur != stop:
            return None  # stuck flat, never hits stop
    return None

print("== factor=1.0, count=None: cases where sequence reaches stop but fix raises ==")
for start in [0, 0.5, 1, 2, 5]:
    for stop in [0.5, 1, 2, 5, 10]:
        if stop < start or stop == 0: continue
        c = reachable(start, stop)
        res = call(backoff, start, stop, factor=1.0)
