            print(f"  MISSED DERIVABLE: backoff({start}, {stop}, factor=1.0) -> {res[1]} but count={c} gives {call(backoff, start, stop, count=c, factor=1.0)[1]}")
        if c is None and res[0] == 'ok':
            print(f"  UNEXPECTED OK: backoff({start}, {stop}, factor=1.0) -> {res[1]}")

print("== report cases ==")
