import math, random, humanize

def core_digits(s):
    # strip prefix letter(s), space, sign, dot -> count numeric digits
    # formats: '10.0 k', '10.0k', '-10.0 m', '1.00 x 10..' etc.
    s = s.split(' x ')[0]
    return len(s.replace('-','').replace('.','').replace(' ','').lstrip('0') and s.replace('-','').replace('.','').replace(' ','') or s.replace('-','').replace('.','').replace(' ',''))

# Simpler: measure raw digit chars of numeric portion only (before space+unit)
def numeric_part(s):
    # numeric part ends before space (if space) — but degree units have no space
    # heuristics: find first char that's a letter (a-z A-Z μ) after optional digits/dot/sign
    out = ''
    for ch in s:
        if ch in '0123456789.-':
            out += ch
        elif out and (ch.isalpha() or ord(ch) > 127):
            break
        elif ch == ' ':
            break
    return out

def nd(s): return len(numeric_part(s).replace('-','').replace('.',''))

random.seed(2024)
over = []
under_exact = []
for _ in range(1000000):
    e = random.randint(-32, 32)
    m = random.uniform(0.1, 1000) * random.choice([1,-1])
    v = m * 10**e
    p = random.randint(1, 6)
