    if nd_count > p:
        over.append((v,p,n,nd_count))
    # detect under: has decimal point and nd_count < p
    np_ = numeric_part(n)
    if '.' in np_ and nd_count < p:
        under_exact.append((v,p,n,nd_count))
print('over precision after fix:', len(over))
for c in over[:30]: print(' ', c)
print('under precision (with decimal):', len(under_exact))
for c in under_exact[:20]: print(' ', c)
