import math, re
from humanize import naturalsize
import humanize.filesize as fs

sufs = {"dec": (fs.suffixes["decimal"], 1000), "bin": (fs.suffixes["binary"], 1024), "gnu": (fs.suffixes["gnu"], 1024)}

def parse(out, gnu):
    m = re.match(r"^(-?[\d.]+(?:e[+-]?\d+)?)(\s*)(\S+)$", out, re.I)
    if not m:
        return None
    return float(m.group(1)), m.group(3)

bad = []
for mode, (suffix, base) in sufs.items():
    kw = {"gnu": True} if mode == "gnu" else ({"binary": True} if mode == "bin" else {})
    n = len(suffix)
    for exp in range(1, n + 1):
        bound = base ** exp
        for v in [bound - 1, int(bound * 0.9999), int(bound - bound * 1e-9), bound + 1, int(bound * 1.0001)]:
            if v < base:
                continue
            for fmt in ["%.1f", "%.2f", "%.0f", "%.3f", "%.4f", "%d", "%.1e"]:
                try:
                    out = naturalsize(v, format=fmt, **kw)
                except Exception as e:
                    bad.append(("EXC", mode, exp, v, fmt, repr(e)))
                    continue
                p = parse(out, mode == "gnu")
