{"intent":"Fuzz indexing and pop bounds","command":"cd work/repo && python3 - <<'PY'
from boltons.setutils import IndexedSet
import random

random.seed(7)
fails = 0
def fail(*a):
    global fails
    fails += 1
    if fails < 20: print('FAIL', *a)

for trial in range(3000):
    base = list(range(random.randint(0, 15)))
    s = IndexedSet(base)
    model = list(base)
    ops = []
    for _ in range(random.randint(1, 12)):
        op = random.choice(['remove', 'pop', 'add', 'reverse', 'sort', 'discard'])
        if op in ('remove', 'discard'):
            if not model: continue
            v = random.choice(model)
            ops.append((op, v))
            s.remove(v); model.remove(v)
        elif op == 'pop':
            if not model: continue
            i = random.randrange(-len(model)-3, len(model)+3)
            ops.append(('pop', i))
            try:
                got = ('ok', s.pop(i))
            except IndexError:
                got = ('err',)
            if -len(model) <= i < len(model):
                exp = ('ok', model.pop(i))
            else:
                exp = ('err',)
            if got != exp: fail('pop', i, got, exp, ops, model)
            if got == ('ok',) and exp == ('ok',):
                pass
        elif op == 'add':
            v = random.randint(0, 20)
            ops.append((op, v))
            s.add(v)
            if v not in model: model.append(v)
        elif op == 'reverse':
            ops.append((op,)); s.reverse(); model.reverse()
        elif op == 'sort':
            ops.append((op,)); s.sort(); model.sort()
        if list(s) != model: fail('iter', ops, list(s), model)
        # slices: forward slices must match list exactly; all slices must match fresh set
        fresh = IndexedSet(model)
        L = len(model)
        for _ in range(6):
            a = random.choice([None, random.randint(-20, 20)])
            b = random.choice([None, random.randint(-20, 20)])
            c = random.choice([None, random.randint(-4, 4)])
            if c == 0: continue
            sl = slice(a, b, c)
            try: got = list(s[sl])
            except Exception as e: got = ('exc', type(e).__name__)
            try: exp = list(fresh[sl])
            except Exception as e: exp = ('exc', type(e).__name__)
            if got != exp: fail('slice-vs-fresh', a, b, c, got, exp, ops, model)
            if c is None or c > 0:
                exp2 = model[a:b:c]
                if got != exp2: fail('slice-vs-list', a, b, c, got, exp2, ops, model)
        # integer indexing
        for i in list(range(-L-3, L+3)):
            try: got = ('ok', s[i])
            except IndexError: got = ('err',)
            except Exception as e: got = ('exc', type(e).__name__)
            exp = ('ok', model[i]) if -L <= i < L else ('err',)
            if got != exp: fail('idx', i, got, exp, ops, model)
print('fails =', fails)
