import itertools, random, traceback
from boltons.setutils import IndexedSet

random.seed(42)
fails = []

# 1. integer index differential vs list (after removals)
vals = list(range(10))
for popset in [[], [2], [0,1,2], [7,8,9], [4]]:
    iset = IndexedSet(vals)
    ref = list(vals)
    for p in popset:
        iset.discard(p); ref.remove(p)
    L = len(ref)
    for idx in range(-L-3, L+3):
        try:
            got = iset[idx]
            gok, gval = True, got
        except IndexError:
            gok, gval = False, None
        try:
            exp = ref[idx]; eok = True
        except IndexError:
            eok = False
        if gok != eok or (gok and gval != exp):
            fails.append(f"getitem {popset} idx={idx}: got {gok, gval} expected {eok, getattr(exp,'__repr__',lambda:None)()}")

# 2. pop differential
for popset in [[], [2], [0,1,2], [7,8,9], [4]]:
    iset = IndexedSet(vals)
    ref = list(vals)
    for p in popset:
        iset.discard(p); ref.remove(p)
    L = len(ref)
    for idx in list(range(-L-3, L+3)):
        a = IndexedSet(iset); b = list(ref)
        try:
            g = a.pop(idx); gok=True
        except IndexError:
            gok=False; g=None
        try:
            e = b.pop(idx); eok=True
        except IndexError:
            eok=False; e=None
        if gok != eok or (gok and (g != e or a != IndexedSet(b))):
            fails.append(f"pop {popset} idx={idx}: got {(gok,g,list(a))} expected {(eok,e,b)}")

print("FAILS:", len(fails))
for f in fails[:40]:
    print(f)
EOF"}

