from humanize import naturalsize
# For every exp, find values where shown rounds to base and check output unit is next & number < base
issues=[]
modes=[(1000,'',{}),(1024,'i',{'binary':True}),(1024,'',{'gnu':True})]
fmts=['%.1f','%.2f','%.3f','%.4f','%.0f','%d']
for base,_,kw in modes:
  for e in range(1,11):
    lo=base**e; hi=base**(e+1)
    # sample densely near lo (where exp might be e-1) and around
    cands=set()
    for frac in range(0,1000):
        v = lo - (hi-lo)*frac//2000
        if v>=base: cands.add(v)
        v2 = lo + (hi-lo)*frac//2000
        if v2>=base: cands.add(v2)
    for v in cands:
      for f in fmts:
        try: s=naturalsize(v,format=f,**kw)
        except Exception as ex: issues.append(('exc',v,f,kw,str(ex))); continue
        # extract leading number
        tok=s.split(' ')[0] if ' ' in s else s
        tok=tok.rstrip('QRTYZEPBMK')  # gnu
        tok=tok.replace('iB','').replace('B','').replace('k','').replace('K','')
        try: x=float(tok)
        except: continue
        if x>=base:
          issues.append(('ge',v,f,dict(kw),s))
        if 0<x<1:
          issues.append(('lt1',v,f,dict(kw),s))
print('issues:',len(issues))
for i in issues[:20]: print(i)
""}

