from more_itertools import value_chain as new_vc

cases = {}

# A: iterator raising TypeError partway (the bug)
def g():
    yield 1; raise TypeError('mid')
cases['generator mid-TypeError'] = (g(), g())
cases['map mid-TypeError'] = (map(abs, [-1,2,'x']), map(abs, [-1,2,'x']))

# B: object whose __iter__ raises TypeError
class BadIter:
    def __iter__(self): raise TypeError('nope')
cases['__iter__ raises TypeError'] = (BadIter(), BadIter())

# C: __iter__ returns a non-iterator (iter() raises TypeError: returned non-iterator)
class NonIter:
    def __iter__(self): return [1,2,3]
cases['__iter__ returns non-iterator'] = (NonIter(), NonIter())

# D: __getitem__ protocol raising TypeError on first access
class SeqFirst:
    def __getitem__(self, i): raise TypeError('first')
cases['__getitem__ TypeError first'] = (SeqFirst(), SeqFirst())

# E: __getitem__ protocol raising TypeError partway
class SeqMid:
    def __getitem__(self, i):
        if i == 0: return i
        raise TypeError('mid getitem')
cases['__getitem__ TypeError mid'] = (SeqMid(), SeqMid())

# F: __getitem__ ending normally (IndexError)
class SeqOK:
    def __getitem__(self, i):
        if i < 3: return i
        raise IndexError
cases['__getitem__ normal'] = (SeqOK(), SeqOK())

# G: plain scalars
cases['scalars'] = ((1, object(), 'ab', b'cd'), (1, object(), 'ab', b'cd'))

# H: class with __iter__ raising TypeError but __next__ working? (iter fails, can't iterate)
class NextOnly:
    def __init__(self): self.i = 0
    def __next__(self):
        self.i += 1
        if self.i > 2: raise StopIteration
        return self.i
cases['only __next__ (no __iter__)'] = (NextOnly(), NextOnly())

for name, (old_v, new_v) in cases.items():
    def run(f, v):
        try:
            return ('ok', list(f(v)))
        except TypeError as e:
            return ('TypeError', str(e))
    o = run(old_vc, old_v)
    n = run(new_vc, new_v)
    flag = 'SAME' if o == n else 'DIFF'
    print(f'{flag} | {name}: old={o} new={n}')
