import sys, math, random, re
sys.path.insert(0, "src")
import humanize.number as hn

# ---- ORIGINAL implementation (before fix) ----
def orig_metric(value, unit="", precision=3):
    if not math.isfinite(value):
        return hn._format_not_finite(value)
    exponent = math.floor(math.log10(abs(value))) if value != 0 else 0
    if exponent >= 33 or exponent < -30:
        return hn.scientific(value, precision-1) + unit
    old_bucket = exponent // 3 * 3
    value /= 10**old_bucket
    def _digits(exp):
        return int(max(0, precision - exp % 3 - 1))
    digits = _digits(exponent)
    if round(abs(value), digits) >= 1000:
        exponent += 3 - exponent % 3
        new_bucket = exponent // 3*3
        value /= 10**(new_bucket-old_bucket)
        digits = _digits(exponent)
    if exponent >= 3:
        ordinal_ = "kMGTPEZYRQ"[exponent//3-1]
    elif exponent < 0:
        ordinal_ = "mμnpfazyrq"[(-exponent-1)//3]
    else:
        ordinal_ = ""
    value_ = format(value, f".{digits}f")
    if not (unit or ordinal_) or unit in ("°","′","″"):
        space = ""
    else:
        space = " "
    return f"{value_}{space}{ordinal_}{unit}"

def sig_count(s):
    num = re.match(r"^-?\d+(\.\d+)?", s)
    if not num: return None
    n = num.group(0)
    body = n.replace("-","").replace(".","").lstrip("0")
    if "." in n:
        return len(body)
    else:
        return len(body.rstrip("0") or "0")

regressions = []
for p in range(0, 8):
    for _ in range(20000):
        e = random.randint(-15, 15)
        v = random.uniform(1,10) * 10**e * random.choice([1,-1])
        for unit in ("", "W"):
            try: o = orig_metric(v, unit, p)
            except Exception as ex: o = f"ERR:{ex}"
            try: n = hn.metric(v, unit, p)
            except Exception as ex: n = f"ERR:{ex}"
            # count sig digits of numeric part
            so, sn = sig_count(o), sig_count(n)
            # flag: new has MORE sig digits than precision while orig did not (a true regression)
            if sn is not None and sn > p and not (so is not None and so > p):
                regressions.append((v,p,unit,o,n,sn))
            # also flag errors or changed results where orig was fine
            if n.startswith("ERR") and not o.startswith("ERR"):
                regressions.append((v,p,unit,o,n,"ERR"))

print("regressions (new worse than orig):", len(regressions))
for r in regressions[:30]:
    print(r)

# Now: does the fix actually fix the bug cases? and is 999.8 preserved?
print("\n--- bug cases ---")
for c in [9996, 99960, 9.9996, 10400, 104000, 999.8]:
    print(c, "orig=", repr(orig_metric(c,"W")), " new=", repr(hn.metric(c,"W")))
EOF"}

