{"intent": "Classify all diffs: check non-rtl ip diffs are pure identifier extensions and rtl diffs for base-version changes", "command": "python3 - <<'PYEOF'
import re, collections
txt = open('review-diff-full.txt').read().split('\n')
entries = []
i = 0
while i < len(txt):
    if txt[i] and not txt[i].startswith('  '):
        k = txt[i]
        o = txt[i+1].strip()[5:]
        n = txt[i+2].strip()[5:]
        entries.append((k, eval(o), eval(n)))
        i += 3
    else:
        i += 1

def split_kv(s):
    # returns (prefix, prerelease_part) roughly: version up to first '-' and after
    if not isinstance(s, str): return (s, None)
    if '-' in s:
        a, b = s.split('-', 1)
        return a, b
    return s, None

ip_bad = []
rtl_bad = []
rtl_kind = collections.Counter()
for k, o, n in entries:
    if k.startswith('coerce|ip|'):
        # expectation: same base, same build, NEW prerelease extends OLD prerelease (or equal)
        ob, op = split_kv(o); nb, np = split_kv(n)
        if o == n: continue
        if ob != nb:
            ip_bad.append((k, o, n, 'base differs')); continue
        # build part after '+' must be same
        obuild = o.split('+')[-1] if '+' in o else None
        nbuild = n.split('+')[-1] if '+' in n else None
        if obuild != nbuild:
            ip_bad.append((k, o, n, 'build differs')); continue
        if op is None or np is None:
            ip_bad.append((k, o, n, 'prerelease appeared/disappeared')); continue
        # OLD prerelease should be a truncation of NEW's: OLD idents are prefix of NEW's last ident
        oids = op.split('+')[0].split('.')
        nids = np.split('+')[0].split('.')
        if oids[:-1] != nids[:-1]:
            ip_bad.append((k, o, n, 'ident list prefix differs')); continue
        if not (nids[-1].startswith(oids[-1]) and len(nids[-1]) > len(oids[-1])):
            ip_bad.append((k, o, n, 'last ident not extended')); continue
    elif k.startswith('coerce|rtl|'):
        ob, op = split_kv(o); nb, np = split_kv(n)
        if ob == nb and (op is None) == (np is None):
            rtl_kind['same base'] += 1
            if op is not None and np is not None:
                if np.startswith(op.split('+')[0].split('.')[0]) or True:
                    pass
        else:
            rtl_kind['BASE or pre presence differs'] += 1
            rtl_bad.append((k, o, n))

print('ip suspicious:', len(ip_bad))
for e in ip_bad[:20]: print(' ', e)
print('rtl kinds:', dict(rtl_kind))
print('rtl bad (base differs or pre presence differs):', len(rtl_bad))
for e in rtl_bad[:30]: print(' ', e)
PYEOF"}

{"intent": "Classify rtl diffs into fixed-vs-regressed and verify non-rtl diffs are pure extensions", "command": "python3 - <<'PYEOF'
import re, collections
txt = open('review-diff-full.txt').read().split('\n')
entries = []
i = 0
while i < len(txt):
    if txt[i] and not txt[i].startswith('  '):
        k, o, n = txt[i], eval(txt[i+1].strip()[5:]), eval(txt[i+2].strip()[5:])
        entries.append((k, o, n)); i += 3
    else:
        i += 1

# 1) verify all ip diffs: OLD is a string-prefix of NEW (modulo trailing build equal)
ip_not_prefix = []
for k, o, n in entries:
    if k.startswith('coerce|ip|') and o != n:
        if not (isinstance(o, str) and isinstance(n, str) and n.startswith(o)):
            ip_not_prefix.append((k, o, n))
print('ip diffs where OLD not prefix of NEW:', len(ip_not_prefix))
for e in ip_not_prefix[:10]: print('  ', e)

# 2) rtl classification
def base(v): return v.split('-')[0] if isinstance(v, str) else None
def is_bare(v): return isinstance(v, str) and '-' not in v
def has_pre(v): return isinstance(v, str) and '-' in v

rtlA = []  # NEW jumped: OLD had base+pre, NEW bare number
rtlB = []  # OLD jumped to bare number, NEW full version (fixed)
rtlC = []  # other
for k, o, n in entries:
    if not k.startswith('coerce|rtl|'): continue
    if o == n: continue
    if has_pre(o) and is_bare(n):
        rtlA.append((k, o, n))
    elif is_bare(o) and has_pre(n):
        rtlB.append((k, o, n))
    else:
        rtlC.append((k, o, n))
print('rtl: NEW bare while OLD had prerelease (suspect regressions):', len(rtlA))
for e in rtlA: print('  ', e)
print('rtl: OLD bare, NEW has prerelease (fixed):', len(rtlB))
print('rtl: other:', len(rtlC))
for e in rtlC[:40]: print('  ', e)
PYEOF"}

