{"intent": "Fix rtl walk to only move to a strictly more right-ward terminus", "command": "cd work/repo && python3 - <<'PY'
from pathlib import Path
p = Path("functions/coerce.js")
s = p.read_text()
old = """    // Walk through the string checking with a /g regexp
    // Manually set the index so as to pick up overlapping matches.
    // Stop when we get a match that ends at the string end, since no
    // coercible string can be more right-ward without the same terminus.
    const coerceRtlRegex = options.includePrerelease ? re[t.COERCERTLFULL] : re[t.COERCERTL]
    let next
    while ((next = coerceRtlRegex.exec(version)) &&
        (!match || match.index + match[0].length !== version.length)
    ) {
      if (!match ||
            next.index + next[0].length !== match.index + match[0].length) {
        match = next
      }
"""
new = """    // Walk through the string checking with a /g regexp
    // Manually set the index so as to pick up overlapping matches.
    // Stop when we get a match that ends at the string end, since no
    // coercible string can be more right-ward without the same terminus.
    // Only a strictly more right-ward terminus replaces the current match:
    // a later-starting candidate may still end earlier (eg, it starts on
    // the digits inside a prerelease identifier), and taking it would
    // discard a more right-ward -- and usually longer -- match.
    const coerceRtlRegex = options.includePrerelease ? re[t.COERCERTLFULL] : re[t.COERCERTL]
    let next
    while ((next = coerceRtlRegex.exec(version)) &&
        (!match || match.index + match[0].length !== version.length)
    ) {
      if (!match ||
            next.index + next[0].length > match.index + match[0].length) {
        match = next
      }
"""
assert s.count(old) == 1, s.count(old)
p.write_text(s.replace(old, new))
print("ok")
PY"}

