{"intent": "Classify every old/new difference", "command": "cd work && node -e "
const neu = require('./repo'), old = require('./repo_baseline')
const ids = ['rc', 'nightly', '7f3c', '4821', '9e1d', '4821.9e1d', 'a7f3', '0', '007', '7f3c.4821', '4821.7f3c', '07f3', 'x-7f3', '1a-2b', '42ab', '99zz', '0z', 'abcdef']
const bases = ['1', '1.2', '1.2.3']
const tails = ['', '+build.9e1d', '+7f3c', '/x', '/dist', ' ', '.4', '-x', ' (nightly.7f3c)', '.9e1d', '/9']
const opts = [undefined, { includePrerelease: true }, { rtl: true }, { rtl: true, includePrerelease: true }, { loose: true, includePrerelease: true }]
const show = v => v ? v.version + '|' + v.build.join('.') : 'null'
const cnt = {}
const flags = []
let total = 0, same = 0
for (const b of bases) for (const id of ids) for (const t of tails) for (const pre of ['', '-' + id]) for (const s of [b + pre + t, 'v' + b + pre + t]) for (const o of opts) {
  total++
  const A = old.coerce(s, o), B = neu.coerce(s, o)
  if (show(A) === show(B)) { same++; continue }
  const ka = show(A), kb = show(B)
  if (kb === 'null') { flags.push(['NEW-NULL', s, o, ka, kb]); continue }
  if (ka === 'null') { flags.push(['OLD-NULL', s, o, ka, kb]); continue }
  const pa = ka.split('|'), pb = kb.split('|')
  if (pa[0] === pb[0]) {
    if (pa[1] === pb[1]) { cnt['ext'] = (cnt['ext']||0)+1 } else { flags.push(['BUILD', s, o, ka, kb]) }
    continue
  }
  const va = pa[0].split('-'), vb = pb[0].split('-')
  if (va[0] === vb[0] && pa[1] === pb[1]) {
    // same base+build: new prerelease must extend old's
    const ia = va[1] ? va.slice(1).join('-') : '', ib = vb[1] ? vb.slice(1).join('-') : ''
    if (ib.startsWith(ia) && ib.length > ia.length) { cnt['pre-ext'] = (cnt['pre-ext']||0)+1 }
    else flags.push(['SAME-BASE-OTHER', s, o, ka, kb])
    continue
  }
  flags.push(['BASE-CHANGED', s, o, ka, kb])
}
console.log('total', total, 'identical', same, 'diff-classified', JSON.stringify(cnt), 'flagged', flags.length)
for (const f of flags) console.log(f[0], JSON.stringify(f[1]), JSON.stringify(f[2]), 'old=' + f[3], 'new=' + f[4])
" > ../out/classify2.log 2>&1; head -c 6000 ../out/classify2.log; echo; wc -l ../out/classify2.log"}

