{"intent": "Re-validate flagged cases with correct semantics", "command": "cd work && python3 - <<'PY'
import re
lines = open('../out/uniq.log').read().splitlines()

def extractable(ver, build, inp):
    """new result must be derivable from input: components appear in order,
    zero-filled .0 parts may be absent from input."""
    base = inp[1:] if inp.startswith('v') else inp
    core, _, pre = ver.partition('-')
    toks = []
    parts = core.split('.')
    if parts[0] != '0' or True: toks.append(parts[0])
    for p in parts[1:]:
        if p != '0': toks.append(p)
    if pre:
        toks += pre.split('.')
    if build:
        toks += build.split('.')
    pos = 0
    for t in toks:
        i = base.find(t, pos)
        if i < 0: return False
        pos = i + len(t)
    return True

kinds, susp = {}, []
for l in lines:
    m = re.match(r'^"(.*)" (\{.*\}|undefined) old=(.*) new=(.*)$', l)
    if not m:
        susp.append(('UNPARSED', l)); continue
    inp, opts, ov, nv = m.groups()
    ov_v, ov_b = (ov.split('|') + [''])[:2]
    nv_v, nv_b = (nv.split('|') + [''])[:2]
    rtl = 'rtl' in opts
    if not extractable(nv_v, nv_b, inp):
        susp.append(('NOT-IN-INPUT', l)); continue
    if nv_v.startswith(ov_v) and nv_b.startswith(ov_b):
        k = 'extension' + ('/rtl' if rtl else '')
        kinds[k] = kinds.get(k, 0) + 1
